      title: col.title,
      position: Number(col.position),
      cards: cards.rows.map(c => ({
        id: c.id,
        columnId: c.column_id,
        text: c.text,
        position: Number(c.position),
        createdAt: c.created_at
      }))
    });
  }
  return board;
}

