async function sendMove(cardId, columnId, beforeId, afterId) {
  try {
    await fetch(`${API_BASE}/cards/${cardId}/move`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        columnId,
        beforeId,
        afterId
      })
