    } else if (beforeIdNum) {
      newPosition = posBefore !== null ? posBefore - 1 : 0;
    } else {
      const maxRes = await db.query('SELECT COALESCE(MAX(position), -1) as maxPos FROM cards WHERE column_id = $1', [columnId]);
