  const cards = await db.query(
    'SELECT id FROM cards WHERE column_id = $1 ORDER BY position, id',
    [columnId]
  );
  const step = 1024;
  for (let i = 0; i < cards.rows.length; i++) {
    await db.exec('UPDATE cards SET position = $1 WHERE id = $2', [i * step, cards.rows[i].id]);
  }
}

