  sourceCol.cards = sourceCol.cards.filter(c => c.id !== cardId);
  // update card columnId temporarily
  card.columnId = targetColumnId;
  // find target column
  const targetCol = state.columns.find(c => c.id === targetColumnId);
  if (!targetCol) return;
