            newPosition = (posAfter + posBefore) / 2;
          }
        }
      }
    } else if (afterIdNum) {
      newPosition = posAfter !== null ? posAfter + 1 : 0;
    } else if (beforeIdNum) {
      newPosition = posBefore !== null ? posBefore - 1 : 0;
