    await fetch(`${API_BASE}/cards/${cardId}/move`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        columnId,
        beforeId,
        afterId
      })
    });
  } catch (e) {
    console.error('Move failed', e);
  }
}

