      // Ensure they are in target column
      const beforeCard = await db.query('SELECT column_id FROM cards WHERE id = $1', [beforeIdNum]);
      const afterCard = await db.query('SELECT column_id FROM cards WHERE id = $1', [afterIdNum]);
