      newPosition = Number(maxRes.rows[0].maxPos) + 1;
    }

    await db.query('UPDATE cards SET column_id = $1, position = $2 WHERE id = $3', [columnId, newPosition, cardId]);

    if (beforeIdNum && afterIdNum && Math.abs(posBefore - posAfter) < 1e-6) {
