    const cur = await db.query('SELECT id, column_id, position FROM cards WHERE id = $1 FOR UPDATE', [cardId]);
    if (cur.rows.length === 0) {
      await db.exec('ROLLBACK');
      return res.status(404).json({ error: 'Card not found' });
    }
