{"path": "/tmp/runs/smokes/muse-q4xl/kanban-board/execution/runs/301/app/frontend/src/main.js", "content": "const API_BASE = 'http://localhost:3001/api';
let state = { columns: [] };

const appEl = document.getElementById('app');

async function loadBoard() {
  const res = await fetch(`${API_BASE}/board`);
  const data = await res.json();
  state.columns = data.columns;
  render();
}

function render() {
  appEl.innerHTML = '';
  state.columns.forEach(col => {
    const colEl = document.createElement('div');
    colEl.className = 'column';
    colEl.dataset.columnId = col.id;

    const title = document.createElement('h2');
    title.textContent = col.title;
    colEl.appendChild(title);

    const cardsContainer = document.createElement('div');
    cardsContainer.className = 'cards';
    cardsContainer.dataset.columnId = col.id;

    // sort cards by position
    const cards = [...col.cards].sort((a, b) => a.position - b.position);
    col.cards = cards;

    cards.forEach(card => {
      const cardEl = document.createElement('div');
      cardEl.className = 'card';
      cardEl.draggable = true;
      cardEl.dataset.cardId = card.id;
      cardEl.textContent = card.text;
      cardsContainer.appendChild(cardEl);
    });
    colEl.appendChild(cardsContainer);

    const addDiv = document.createElement('div');
    addDiv.className = 'add-card';
    const input = document.createElement('input');
    input.placeholder = 'New card';
    const btn = document.createElement('button');
    btn.textContent = 'Add';
    addDiv.appendChild(input);
    addDiv.appendChild(btn);
    colEl.appendChild(addDiv);

    appEl.appendChild(colEl);

    // add card handler
    btn.onclick = async () => {
      const text = input.value.trim();
      if (!text) return;
      input.value = '';
      try {
        const res = await fetch(`${API_BASE}/cards`, {
          method: 'POST',
