function connectSSE() {
  eventSource = new EventSource(`${API_BASE}/stream`);
  eventSource.addEventListener('card-created', e => {
    const { card } = JSON.parse(e.data);
    // Update state
    const col = state.columns.find(c => c.id === card.columnId);
    if (col) {
