    }
    // Re-sort by position
    state.columns.forEach(col => {
      col.cards.sort((a, b) => a.position - b.position);
    });
    render();
  });
  eventSource.onerror = () => {
    console.warn('SSE error, reconnecting...');
    setTimeout(connectSSE, 2000);
  };
}

